#!/bin/bash
# Minimal systemctl shim for containers without systemd as PID 1.
# Supports the subset of verbs used by the Qisutu installer.
STATE_DIR=/run/systemd-mock
mkdir -p "$STATE_DIR"
NOW=0
VERB=""
UNITS=()
for a in "$@"; do
    case "$a" in
        --now) NOW=1 ;;
        --quiet|--no-pager|--system|--no-ask-password|--no-block|--full|--plain) ;;
        -*) ;;
        *)
            if [ -z "$VERB" ]; then VERB="$a"; else UNITS+=("$a"); fi
            ;;
    esac
done

base() { local u="${1##*/}"; echo "${u%.service}"; }

start_one() {
    local u="$1"
    local n; n="$(base "$u")"
    case "$u" in
        *.path) return 0 ;;
        *install-complete*) return 0 ;;
    esac
    case "$n" in
        apache2) apache2ctl start >/dev/null 2>&1 || /usr/sbin/apachectl start >/dev/null 2>&1 || true ;;
        httpd)  /usr/sbin/httpd -k start >/dev/null 2>&1 || true ;;
        mariadb|mysql) service mariadb start >/dev/null 2>&1 || service mysql start >/dev/null 2>&1 || true ;;
        qisutu|qisutu-*) service "$n" start >/dev/null 2>&1 || true ;;
        *) service "$n" start >/dev/null 2>&1 || true ;;
    esac
    return 0
}

stop_one() {
    local u="$1"
    local n; n="$(base "$u")"
    case "$n" in
        apache2) apache2ctl stop >/dev/null 2>&1 || true ;;
        mariadb|mysql) service mariadb stop >/dev/null 2>&1 || true ;;
        *) service "$n" stop >/dev/null 2>&1 || true ;;
    esac
    return 0
}

active_one() {
    local u="$1"
    local n; n="$(base "$u")"
    case "$n" in
        apache2) pgrep -x apache2 >/dev/null 2>&1 ;;
        mariadb|mysql) pgrep -x mariadbd >/dev/null 2>&1 || pgrep -x mysqld >/dev/null 2>&1 ;;
        *) pgrep -f "$n" >/dev/null 2>&1 ;;
    esac
}

case "$VERB" in
    daemon-reload|daemon-reexec) exit 0 ;;
    enable)
        for u in "${UNITS[@]}"; do touch "$STATE_DIR/$u.enabled"; done
        [ "$NOW" -eq 1 ] && for u in "${UNITS[@]}"; do start_one "$u"; done
        exit 0 ;;
    disable)
        for u in "${UNITS[@]}"; do rm -f "$STATE_DIR/$u.enabled"; done
        [ "$NOW" -eq 1 ] && for u in "${UNITS[@]}"; do stop_one "$u"; done
        exit 0 ;;
    start) for u in "${UNITS[@]}"; do start_one "$u"; done; exit 0 ;;
    stop) for u in "${UNITS[@]}"; do stop_one "$u"; done; exit 0 ;;
    restart|try-restart|reload-or-restart)
        for u in "${UNITS[@]}"; do stop_one "$u"; start_one "$u"; done; exit 0 ;;
    reload) exit 0 ;;
    is-active)
        rc=0
        for u in "${UNITS[@]}"; do active_one "$u" || rc=1; done
        [ "$rc" -eq 0 ] && echo active || echo inactive
        exit $rc ;;
    is-enabled)
        rc=0
        for u in "${UNITS[@]}"; do [ -e "$STATE_DIR/$u.enabled" ] || rc=1; done
        [ "$rc" -eq 0 ] && echo enabled || echo disabled
        exit $rc ;;
    status)
        exit 0 ;;
    mask|unmask) exit 0 ;;
    *) exit 0 ;;
esac
SHIM
chmod +x /usr/local/bin/systemctl
systemctl --version 2>&1 | head -1; systemctl daemon-reload; echo "shim ok rc=$?"

