    my (%Param) = @_;
    my $DBH = $Param{DBH};
    my $DBName = $Param{DBName};
    return if !$DBH || $DBName !~ m{\A[A-Za-z0-9_]+\z};
    eval {
        $DBH->do("DROP DATABASE IF EXISTS `$DBName`");
        if ( $Param{Existed} ) {
            $DBH->do("CREATE DATABASE `$DBName` CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci");
