        if ( $Param{DropUser} && $Param{DBUser} && $Param{GrantHost} ) {
            my $Account = $DBH->quote( $Param{DBUser} ) . '@' . $DBH->quote( $Param{GrantHost} );
            $DBH->do("DROP USER IF EXISTS $Account");
        }
    };
}

